    data class Preference<T>(val key: String, val default: T?)

    fun editor(edit: SharedPreferences.Editor.() -> Unit) {
        preferences.edit().apply(edit).apply()
    }

    fun getBoolean(preference: Preference<Boolean>): Boolean? {
